import{_ as i,c as a,o as t,ag as s}from"./chunks/framework.DRADY2L-.js";const u=JSON.parse('{"title":"Buddai Web App","description":"","frontmatter":{},"headers":[],"relativePath":"web_app/index.md","filePath":"web_app/index.md"}'),n={name:"web_app/index.md"};function l(o,e,d,r,c,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="buddai-web-app" tabindex="-1">Buddai Web App <a class="header-anchor" href="#buddai-web-app" aria-label="Permalink to &quot;Buddai Web App&quot;">​</a></h1><p>Modern web dashboard for managing Buddai agents, tools, and conversations. Built with React 18, Vite, TailwindCSS, and Lucide icons, the app provides both functional workflows for daily operations and a clean technical foundation for extensibility.</p><h2 id="functional-overview" tabindex="-1">Functional Overview <a class="header-anchor" href="#functional-overview" aria-label="Permalink to &quot;Functional Overview&quot;">​</a></h2><ul><li><p><strong>Authentication</strong></p><ul><li>Login screen with dark/light toggle.</li><li>Demo credentials banner (when mocks enabled).</li></ul></li><li><p><strong>Agents Management</strong></p><ul><li>Responsive sidebar listing all agents with create action.</li><li>Markdown-based agent editor (model selection, temperature slider, tool assignment, prompt editing).</li><li>AI-assisted prompt tweaks via inline chat input.</li></ul></li><li><p><strong>Chat Experience</strong></p><ul><li>Multi-agent chat interface with back navigation.</li><li>Loading indicators, error banners, progress handling, and plain text rendering.</li></ul></li><li><p><strong>Settings</strong></p><ul><li>Backend URL and configuration editing aligned with Buddai’s MCP tool chain.</li><li>Tool registry visualization and client connection panels.</li></ul></li><li><p><strong>Dark Mode</strong></p><ul><li>Global toggle with persisted preference.</li></ul></li></ul><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>Description</th></tr></thead><tbody><tr><td>Login</td><td>Access control with branding and demo hints (mocks).</td></tr><tr><td>Agents</td><td>High-level roster view with creation workflow.</td></tr><tr><td>Agent Editor</td><td>Full agent configuration, prompt editing, tool management.</td></tr><tr><td>Chat</td><td>Conversational UI for selected agent.</td></tr><tr><td>Settings</td><td>System-level configuration (models, tools, connections).</td></tr></tbody></table><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>Node.js ≥ 20.x</li><li>npm ≥ 10.x</li></ul><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h3 id="development-with-mock-services-default" tabindex="-1">Development with Mock Services (default) <a class="header-anchor" href="#development-with-mock-services-default" aria-label="Permalink to &quot;Development with Mock Services (default)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><ul><li>Reads <code>.env.development</code> (<code>VITE_USE_MOCKS=true</code>).</li><li>Demo credentials appear on login (<code>admin/password</code>, <code>user/password</code>, <code>demo/password</code>).</li><li>LocalStorage persists agents, settings, auth tokens.</li></ul><h3 id="development-against-real-api" tabindex="-1">Development Against Real API <a class="header-anchor" href="#development-against-real-api" aria-label="Permalink to &quot;Development Against Real API&quot;">​</a></h3><ol><li>Create <code>.env.development.local</code> (or unset the env var):<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_USE_MOCKS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">false</span></span></code></pre></div></li><li>Ensure <code>apiReal.tsx</code> points to live endpoints.</li><li>Run the dev server:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div></li></ol><h3 id="production-build" tabindex="-1">Production Build <a class="header-anchor" href="#production-build" aria-label="Permalink to &quot;Production Build&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><ul><li>Outputs static assets under <code>dist/</code> (Vite).</li><li>Deploy via any static host or edge platform.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><ul><li><p><strong>Environment Variables</strong></p><ul><li><code>VITE_USE_MOCKS</code> – toggles mock vs real API services (<code>true</code>, <code>1</code>, <code>mocks</code>, etc.).</li><li>Additional MCP/tool secrets flow through the backend; not stored in the SPA.</li></ul></li><li><p><strong>Local Storage Keys</strong></p><ul><li><code>buddai_agents</code>, <code>buddai_settings</code> – persisted mock data sets.</li><li><code>buddai_auth_token</code>, <code>buddai_user</code> – auth session in mock mode.</li><li><code>buddai_backend_url</code> – last-used backend URL.</li></ul></li></ul><h2 id="architecture-key-modules" tabindex="-1">Architecture &amp; Key Modules <a class="header-anchor" href="#architecture-key-modules" aria-label="Permalink to &quot;Architecture &amp; Key Modules&quot;">​</a></h2><ul><li><code>src/App.tsx</code> – root layout, routing between screens, theme handling.</li><li><code>src/DataProviders.tsx</code> – hooks for agents, settings, auth, dark mode, plus supervisor agent factory.</li><li><code>src/components/</code> – UI composables (AgentList, MarkdownEditor, ChatInterface, Settings, Login).</li><li><code>src/services/api.tsx</code> – switchable API layer deciding between <code>apiMock</code> and <code>apiReal</code>.</li><li><code>src/services/apiMock.tsx</code> – feature-rich mock implementation (CRUD, auth, chat history).</li><li><code>src/services/apiReal.tsx</code> – live API wiring (placeholder for real backend integration).</li><li><code>src/components/ui/</code> – Shadcn-based primitives (Button, Card, Dialog, etc.).</li></ul><h2 id="styling" tabindex="-1">Styling <a class="header-anchor" href="#styling" aria-label="Permalink to &quot;Styling&quot;">​</a></h2><ul><li>TailwindCSS utility classes with global overrides in <code>src/index.css</code>.</li><li>Dark mode powered by CSS variables + toggled via contextual state.</li></ul><h2 id="testing-quality" tabindex="-1">Testing &amp; Quality <a class="header-anchor" href="#testing-quality" aria-label="Permalink to &quot;Testing &amp; Quality&quot;">​</a></h2><ul><li>Manual validation recommended via <code>npm run dev</code> with both mock and real modes.</li><li>Future enhancements may include automated tests (Jest/Playwright) and story-driven component previews.</li></ul><h2 id="roadmap-ideas" tabindex="-1">Roadmap Ideas <a class="header-anchor" href="#roadmap-ideas" aria-label="Permalink to &quot;Roadmap Ideas&quot;">​</a></h2><ul><li>Persist dark-mode preference across sessions.</li><li>Add agent search/filter chips in sidebar.</li><li>Extend chat with streaming responses and attachments.</li><li>Integrate toast notifications for save/errors.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Internal Buddai project. Contact the maintainers for usage or distribution details.</p>',31)])])}const g=i(n,[["render",l]]);export{u as __pageData,g as default};
